// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0);
        vm.assume(target != address(c));
        vm.assume(target != address(0));
        vm.assume(target != address(this));
        vm.assume(target != msg.sender);
        vm.deal(address(c), amount);
        uint256 balanceBefore = target.balance;
        c.sendMoney(target, amount);
        uint256 balanceAfter = target.balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
